import { NextResponse } from 'next/server';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { query } from '@/lib/db';

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || 'dummy_gemini_key');

const DRAFT_EMAIL_SYSTEM_PROMPT = `
You are an administrative assistant at the French Institute of Greece (IFG). Your task is to draft a response email to a student or parent inquiry based on the provided context (policies, templates).

Strictly emulate the IFG 'MAILS TYPES' templates and adhere to the following rules:

1. Tone: Professional, welcoming, precise, and administrative.
2. Greetings: Always open with a formal address, such as "Αγαπητή/έ κυρία/κύριε [Name]," or "Καλημέρα σας," if the name is unknown (adapt to the language of the email).
3. Sign-offs: Always use a formal sign-off: "Παραμένουμε στη διάθεσή σας. / Με εκτίμηση," at the end of the email (adapt to the language of the email).
4. Formatting: 
   - Use bullet points for listing payment options (e.g., installments vs. full payment).
   - Bold crucial details such as the **IBAN**, **start dates**, and the **10€ placement test fee**.
5. Language: Detect and draft the email in the same language as the incoming email (French, English, or Greek). DO NOT mix languages.
6. Conversation Rules (CRITICAL):
   - When a user asks about course enrollment or pricing, DO NOT immediately dump all the pricing information if details are missing.
   - Before giving a final answer for course registration, the drafted email MUST ask the following clarifying questions if they haven't already provided the information:
     - "Were you a student at the Institut Français de Grèce last year (2025-2026)?"
     - "If not, did you acquire your most recent French diploma (e.g., B1) in the past 2 to 3 years (between 2024 and 2026)?"
   - Why? Briefly explain that this determines if they need an evaluation or qualify for the 5% returning student discount.
7. Evaluation Difference: For Adults, the placement test is an online procedure that costs 10€. For Teens/Ados, the evaluation is a FREE session with one of our professors.
8. Audience Separation: If the sender specifies "Adults" (or 17+), ONLY draft information for Adult classes. NEVER draft information about Teens/Ados unless explicitly requested. The opposite is also true.

Write ONLY the email draft, nothing else. Do not add introductory or concluding remarks outside the email text itself.
`;

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { emailBody, senderName = '' } = body;

    if (!emailBody) {
      return NextResponse.json({ error: 'emailBody is required' }, { status: 400 });
    }

    const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || '');
    const embeddingModel = genAI.getGenerativeModel({ model: "gemini-embedding-2" });
    const emailModel = genAI.getGenerativeModel({ 
      model: "gemini-3.5-flash",
      systemInstruction: DRAFT_EMAIL_SYSTEM_PROMPT 
    });

    // 1. Generate embedding for user email
    const embeddingResponse = await embeddingModel.embedContent(emailBody);
    const queryEmbedding = embeddingResponse.embedding.values;

    // 2. Retrieve context using raw SQL pgvector distance
    let documents: any[] = [];
    try {
      const dbRes = await query(
        'SELECT id, content, source_type, source_name, metadata FROM documents ORDER BY embedding <-> $1 LIMIT $2',
        [JSON.stringify(queryEmbedding), 8]
      );
      documents = dbRes.rows;
    } catch (err) {
      console.error('Database query failed:', err);
      throw new Error('Database query failed');
    }

    // 3. Assemble retrieved chunks into a context block
    let contextBlock = '';
    if (documents && documents.length > 0) {
      contextBlock = documents.map((doc: any, index: number) => {
        const metadata = typeof doc.metadata === 'string' ? JSON.parse(doc.metadata) : doc.metadata;
        const sectionHeading = metadata.document_title ? ` - ${metadata.document_title}` : '';
        return `[Source ${index + 1}: ${doc.source_name} (${doc.source_type})${sectionHeading}]\n${doc.content}\n`;
      }).join('\n');
    } else {
      contextBlock = "No relevant context found.";
    }

    // 4. Call Gemini API to generate email draft
    const chatModel = genAI.getGenerativeModel({ 
      model: "gemini-3.5-flash",
      systemInstruction: DRAFT_EMAIL_SYSTEM_PROMPT 
    });

    const prompt = `Context Information from IFG datasets:\n---\n${contextBlock}\n---\n\nDraft an email response to the following inquiry. Use the name "${senderName}" if applicable.\n\nIncoming Email Inquiry:\n${emailBody}`;

    const response = await chatModel.generateContent(prompt);
    let draftText = response.response.text();

    // 5. Return the draft and sources
    return NextResponse.json({
      draft: draftText,
      sources: documents ? documents.map((d: any) => ({ source_name: d.source_name, source_type: d.source_type })) : [],
    });

  } catch (error: any) {
    console.error('Draft API Error:', error);
    return NextResponse.json({ error: 'Internal Server Error', details: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { pool } from '@/lib/db';
import { sendEmail } from '@/lib/email';
import { SYSTEM_PROMPT } from '@/config/systemPrompt';

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || '');
const embeddingModel = genAI.getGenerativeModel({ model: "gemini-embedding-2" });
const emailModel = genAI.getGenerativeModel({ model: "gemini-3.5-flash" });

export async function POST(req: NextRequest) {
  try {
    const payload = await req.json();
    const {
      studentName,
      studentEmail,
      studentAge,
      parentName,
      previousLevel,
      hasDelfDalf,
      delfDalfDate,
      discountCategory
    } = payload;

    if (!studentEmail) {
      return NextResponse.json({ error: 'studentEmail is required' }, { status: 400 });
    }

    // 1. Create a query string from the payload
    const query = `
      Student Name: ${studentName || 'N/A'}
      Age: ${studentAge || 'N/A'} (Determine if Kids/Teens or Adults based on policies)
      Parent Name: ${parentName || 'N/A'}
      Previous Level: ${previousLevel || 'None'}
      Has DELF/DALF: ${hasDelfDalf ? 'Yes' : 'No'} (Date: ${delfDalfDate || 'N/A'})
      Discount Category: ${discountCategory || 'None'}
      Determine placement test requirements, pricing, and discount rules. Draft an email to this student based on IFG policies.
    `;

    // 2. Embed the query
    const embeddingResult = await embeddingModel.embedContent(query);
    const embedding = embeddingResult.embedding.values;

    // 3. Search vector DB for relevant context
    const dbResult = await pool.query(
      `SELECT content, 1 - (embedding <=> $1::vector) AS similarity 
       FROM documents 
       ORDER BY embedding <=> $1::vector 
       LIMIT 8`,
      [JSON.stringify(embedding)]
    );
    const contextText = dbResult.rows.map((row) => row.content).join('\n\n');

    // 4. Draft Email using Gemini 2.5 Pro
    const prompt = `
      You are IFG Assistant, the administrative assistant for the French Institute of Greece.

      Below is the information received from a Google Form submission:
      ${query}

      And here are the relevant policies from the database:
      ${contextText}

      Based on the provided form data and policies, please determine:
      1. Which demographic (Kids/Teens vs Adults) this student belongs to.
      2. If they need a placement test (e.g. if their DELF/DALF is older than December 2023, they might need one, check the rules!).
      3. The appropriate pricing and whether their discount category applies.

      Draft a professional, welcoming email directly addressing the student (or parent, if it's a child). 
      The email MUST be provided in both Greek and French (one after the other in the same email body).
      Emulate the tone of IFG (formal, precise, administrative).
      Return ONLY the email draft text without any markdown or extra commentary.
    `;

    const chatSession = emailModel.startChat({
      history: [
        {
          role: "user",
          parts: [{ text: SYSTEM_PROMPT }]
        },
        {
          role: "model",
          parts: [{ text: "Understood. I am IFG Assistant. I will adhere to all policies and emulate the IFG persona." }]
        }
      ]
    });

    const response = await chatSession.sendMessage(prompt);
    const draftText = response.response.text();

    // 5. Send the email (mock or real)
    try {
      await sendEmail(studentEmail, 'Bienvenue à l\'IFG / Καλώς ήρθατε στο IFG', draftText);
    } catch (e) {
      console.warn("Failed to send email. SMTP might not be configured.", e);
    }

    return NextResponse.json({ success: true, draft: draftText });

  } catch (err: any) {
    console.error('Google Form Webhook Error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

'use client';

import React, { useEffect, useState } from 'react';
import { Loader2, Send, Edit, RefreshCw } from 'lucide-react';

export default function OutlookTaskpane() {
  const [isOfficeInitialized, setIsOfficeInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [emailBody, setEmailBody] = useState('');
  const [senderName, setSenderName] = useState('');
  const [draft, setDraft] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    // Initialize Office.js
    if (typeof (window as any).Office !== 'undefined') {
      (window as any).Office.onReady((info: any) => {
        if (info.host === (window as any).Office.HostType.Outlook) {
          setIsOfficeInitialized(true);
        }
      });
    }
  }, []);

  const handleGenerateDraft = async () => {
    if (!isOfficeInitialized) {
      setError('Office.js is not initialized. Are you running this in Outlook?');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess(false);

    try {
      // 1. Get the current item (email)
      const item = (window as any).Office.context.mailbox.item;

      if (!item) {
        throw new Error('No email item found in the current context.');
      }

      setSenderName(item.sender?.displayName || item.sender?.emailAddress || '');

      // 2. Read the body of the email
      item.body.getAsync((window as any).Office.CoercionType.Text, async (result: any) => {
        if (result.status === (window as any).Office.AsyncResultStatus.Failed) {
          setError('Failed to read email body: ' + result.error.message);
          setLoading(false);
          return;
        }

        const bodyText = result.value;
        setEmailBody(bodyText);

        // 3. Call our Next.js API route to generate the draft
        try {
          const res = await fetch('/api/draft-email', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ emailBody: bodyText, senderName: item.sender?.displayName || '' }),
          });

          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Failed to generate draft');

          setDraft(data.draft);
        } catch (apiErr: any) {
          setError(apiErr.message || 'API request failed');
        } finally {
          setLoading(false);
        }
      });
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred');
      setLoading(false);
    }
  };

  const handleInsertDraft = () => {
    if (!isOfficeInitialized || !draft) return;

    const item = (window as any).Office.context.mailbox.item;
    if (!item) return;

    // To insert the draft, we call displayReplyForm to open the reply window and inject the text.
    // Replace newlines with <br> for HTML injection if needed, or use CoercionType.Text if injecting directly.
    // Outlook add-ins have a specific way to reply. displayReplyForm is the standard.

    item.displayReplyForm({
      htmlBody: draft.replace(/\n/g, '<br>'),
      callback: (result: any) => {
        if (result.status === (window as any).Office.AsyncResultStatus.Failed) {
          setError('Failed to insert draft: ' + result.error.message);
        } else {
          setSuccess(true);
          setTimeout(() => setSuccess(false), 3000);
        }
      }
    });
  };

  if (!isOfficeInitialized) {
    return (
      <div className="flex items-center justify-center h-full p-4 text-center text-slate-500">
        <p>Loading Outlook integration... Please ensure you are viewing this within an Outlook Taskpane.</p>
      </div>
    );
  }

  return (
    <div className="p-4 h-full flex flex-col bg-slate-50">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-lg font-semibold text-slate-800">IFG Assistant</h1>
        <button 
          onClick={handleGenerateDraft} 
          disabled={loading}
          className="p-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50 transition-colors"
          title="Generate Draft"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
        </button>
      </div>

      {error && (
        <div className="p-3 mb-4 text-sm text-red-700 bg-red-100 rounded-md border border-red-200">
          {error}
        </div>
      )}

      {success && (
        <div className="p-3 mb-4 text-sm text-green-700 bg-green-100 rounded-md border border-green-200">
          Draft inserted successfully! Review the email before sending.
        </div>
      )}

      <div className="flex-1 overflow-y-auto mb-4 bg-white rounded-md border border-slate-200 shadow-sm p-3">
        {loading ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-400 gap-2">
            <Loader2 className="w-6 h-6 animate-spin" />
            <p className="text-sm">Reading policies & drafting reply...</p>
          </div>
        ) : draft ? (
          <div className="text-sm text-slate-700 whitespace-pre-wrap">
            {draft}
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-slate-400 text-center text-sm px-4">
            <Edit className="w-8 h-8 mb-2 opacity-50" />
            <p>Click the generate button to read this email and draft a policy-compliant response.</p>
          </div>
        )}
      </div>

      <button
        onClick={handleInsertDraft}
        disabled={loading || !draft}
        className="w-full py-3 px-4 bg-emerald-600 text-white rounded-md hover:bg-emerald-700 disabled:opacity-50 transition-colors font-medium flex items-center justify-center gap-2 shadow-sm"
      >
        <Send className="w-4 h-4" />
        Insert Draft in Reply
      </button>
    </div>
  );
}

import * as fs from 'fs';
import * as path from 'path';
import * as cheerio from 'cheerio';
import * as mammoth from 'mammoth';
import * as xlsx from 'xlsx';
import * as dotenv from 'dotenv';

dotenv.config({ path: '.env.local' });
dotenv.config();

import { pool } from '../lib/db';
import { chunkText } from '../lib/chunking';
import { mapUrlToSection } from '../lib/sectionMapping';
import { embedText } from '../lib/gemini';

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

// Proactive delay between embedding calls to stay within free-tier Gemini
// rate limits; embedText() also retries transient 429s on top of this.
const EMBED_DELAY_MS = 4500;

const DEFAULT_SITEMAP_INDEX = 'https://www.ifg.gr/sitemap_index.xml';

// Confirmed live via robots.txt (Sitemap: https://www.ifg.gr/sitemap_index.xml)
// and inspection of its nested sitemaps. Excluded categories:
// - category-/post_tag-/author-sitemap: thin, auto-generated taxonomy archive
//   pages (lists of links, no unique content worth embedding).
// - event-/event_category-/event_group-/newsletter-sitemap: high-volume
//   (750-1000+ URLs each) and time-sensitive; including them risks surfacing
//   expired event dates/newsletter content as current, and would burn a large
//   share of the free-tier embedding quota on lower-value content. Revisit if
//   event- or newsletter-specific Q&A becomes a product priority.
const EXCLUDED_SITEMAP_PATTERNS = [
  /category-sitemap/i,
  /post_tag-sitemap/i,
  /author-sitemap/i,
  /event-sitemap/i,
  /event_category-sitemap/i,
  /event_group-sitemap/i,
  /newsletter-sitemap/i,
];

// /news/ posts are time-sensitive (announcements, exam result posts, etc.);
// skip ones older than this so stale announcements don't get treated as
// current fact. Configurable since "how far back is relevant" is a judgment
// call that may need tuning after seeing real ingested content.
const TIME_SENSITIVE_PATH_PREFIXES = ['/news/'];
const NEWS_MAX_AGE_DAYS = Number(process.env.NEWS_MAX_AGE_DAYS ?? 365);

// Confirmed via live fetch: these are empty admin scratch/test pages (e.g.
// /test-xyz/ contains nothing but its own title) that ended up in
// page-sitemap.xml. They add near-zero value and occasionally surface as a
// weak-signal match when nothing else scores well. Skip any URL whose last
// path segment starts with "test".
const JUNK_PATH_PATTERN = /\/test[^/]*\/?$/i;

interface SitemapUrlEntry {
  loc: string;
  lastmod?: string;
}

async function fetchSitemapEntries(sitemapUrl: string, limit?: number): Promise<SitemapUrlEntry[]> {
  const res = await fetch(sitemapUrl);
  const xml = await res.text();

  if (/<sitemapindex/i.test(xml)) {
    const nestedLocs = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map((m) => m[1]);
    let entries: SitemapUrlEntry[] = [];
    for (const nested of nestedLocs) {
      if (EXCLUDED_SITEMAP_PATTERNS.some((pattern) => pattern.test(nested))) {
        console.log(`  Skipping sitemap (excluded category): ${nested}`);
        continue;
      }
      const remaining = limit ? limit - entries.length : undefined;
      if (remaining !== undefined && remaining <= 0) break;
      entries = entries.concat(await fetchSitemapEntries(nested, remaining));
    }
    return entries;
  }

  const urlBlocks = [...xml.matchAll(/<url>([\s\S]*?)<\/url>/g)];
  const entries: SitemapUrlEntry[] = [];
  const seen = new Set<string>();
  for (const block of urlBlocks) {
    const locMatch = /<loc>(.*?)<\/loc>/.exec(block[1]);
    if (!locMatch) continue;
    const loc = locMatch[1].trim();
    if (seen.has(loc)) continue; // Yoast sitemaps sometimes list duplicate entries
    seen.add(loc);
    const lastmodMatch = /<lastmod>(.*?)<\/lastmod>/.exec(block[1]);
    entries.push({ loc, lastmod: lastmodMatch?.[1] });
    if (limit && entries.length >= limit) break;
  }
  return entries;
}

function isStaleTimeSensitivePage(entry: SitemapUrlEntry): boolean {
  let pathname: string;
  try {
    pathname = new URL(entry.loc).pathname;
  } catch {
    return false;
  }
  const isTimeSensitive = TIME_SENSITIVE_PATH_PREFIXES.some((prefix) => pathname.startsWith(prefix));
  if (!isTimeSensitive || !entry.lastmod) return false;
  const ageDays = (Date.now() - new Date(entry.lastmod).getTime()) / (1000 * 60 * 60 * 24);
  return ageDays > NEWS_MAX_AGE_DAYS;
}

// Cloudflare's email-obfuscation ("Email Protection") replaces mailto links
// with a JS-decoded span; since we don't execute JS, cheerio sees the raw
// fallback text literally reading "[email protected]" -- confirmed present on
// several real ifg.gr pages (e.g. /oi-choroi-mas/) and, before this fix, was
// faithfully repeated by the model as if it were a real email in at least
// one live test answer. Strip it rather than ingest it as content.
const CLOUDFLARE_EMAIL_PLACEHOLDER = /\[email\s*protected\]/gi;

// Joins block-level element text with paragraph breaks instead of calling
// $('body').text() directly, which just concatenates every text node with
// whatever whitespace happened to be in the source HTML. Preserving real
// paragraph boundaries lets chunkText()'s paragraph-aware splitting actually
// do its job on scraped pages instead of degrading to one giant blob.
function extractBodyText($: cheerio.CheerioAPI): string {
  const blocks: string[] = [];
  $('body')
    .find('h1, h2, h3, h4, h5, h6, p, li, td, blockquote')
    .each((_, el) => {
      const text = $(el)
        .text()
        .replace(CLOUDFLARE_EMAIL_PLACEHOLDER, '')
        .replace(/[ \t]+/g, ' ')
        .trim();
      if (text) blocks.push(text);
    });
  if (blocks.length > 0) return blocks.join('\n\n');
  return $('body').text().replace(CLOUDFLARE_EMAIL_PLACEHOLDER, '').replace(/\s+/g, ' ').trim();
}

async function upsertDocumentChunks(
  sourceName: string,
  sourceType: string,
  chunks: string[],
  metadataBase: Record<string, unknown>,
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('DELETE FROM documents WHERE source_name = $1', [sourceName]);
    for (let i = 0; i < chunks.length; i++) {
      const embedding = await embedText(chunks[i]);
      await client.query(
        'INSERT INTO documents (content, embedding, source_type, source_name, metadata) VALUES ($1, $2, $3, $4, $5)',
        [chunks[i], JSON.stringify(embedding), sourceType, sourceName, { ...metadataBase, chunk_index: i }],
      );
      await sleep(EMBED_DELAY_MS);
    }
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

async function ingestWebsitePage(entry: SitemapUrlEntry): Promise<void> {
  const url = entry.loc;
  try {
    const pageRes = await fetch(url);
    if (!pageRes.ok) {
      console.log(`  ✗ ${url} -> HTTP ${pageRes.status}, skipping`);
      return;
    }
    const html = await pageRes.text();
    const $ = cheerio.load(html);
    $('nav, header, footer, script, style, noscript, iframe').remove();

    const title = $('title').text().trim() || url;
    const mainText = extractBodyText($);
    if (!mainText) {
      console.log(`  ✗ ${url} -> no text content, skipping`);
      return;
    }

    const section = mapUrlToSection(url);
    const chunks = chunkText(mainText);
    await upsertDocumentChunks(url, 'website', chunks, {
      page_title: title,
      ...(section ? { section } : {}),
    });
    console.log(`  ✓ ${url} -> ${chunks.length} chunk(s)${section ? ` [${section}]` : ' [unmapped]'}`);
  } catch (err) {
    console.error(`  ✗ Failed to process ${url}:`, err);
  }
}

async function ingestWebsite(sitemapIndexUrl: string, limit?: number): Promise<void> {
  console.log(`Fetching sitemap: ${sitemapIndexUrl}`);
  const entries = await fetchSitemapEntries(sitemapIndexUrl, limit);
  console.log(`Found ${entries.length} candidate URL(s) after excluding thin/time-sensitive sitemap categories.`);

  let processed = 0;
  for (const entry of entries) {
    if (isStaleTimeSensitivePage(entry)) {
      console.log(`  Skipping stale news/blog page (older than ${NEWS_MAX_AGE_DAYS}d): ${entry.loc}`);
      continue;
    }
    if (JUNK_PATH_PATTERN.test(entry.loc)) {
      console.log(`  Skipping junk/test page: ${entry.loc}`);
      continue;
    }
    await ingestWebsitePage(entry);
    processed++;
    if (limit && processed >= limit) break;
  }
}

async function ingestPDFs(directoryPath: string): Promise<void> {
  if (!fs.existsSync(directoryPath)) return;
  console.log(`Reading PDFs from ${directoryPath}...`);
  const files = fs.readdirSync(directoryPath).filter((f) => f.toLowerCase().endsWith('.pdf'));
  for (const file of files) {
    console.log(`  Processing PDF: ${file}`);
    try {
      const filePath = path.join(directoryPath, file);
      const dataBuffer = fs.readFileSync(filePath);
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const pdfParse = require('pdf-parse');
      const data = await pdfParse(dataBuffer);
      const text: string = data.text.trim();
      const chunks = chunkText(text);
      await upsertDocumentChunks(file, 'pdf', chunks, { document_title: file.replace(/\.pdf$/i, '') });
      console.log(`  ✓ ${file} -> ${chunks.length} chunk(s)`);
    } catch (err) {
      console.error(`  ✗ Failed to process PDF ${file}:`, err);
    }
  }
}

async function ingestDocx(directoryPath: string): Promise<void> {
  if (!fs.existsSync(directoryPath)) return;
  console.log(`Reading DOCX from ${directoryPath}...`);
  const files = fs.readdirSync(directoryPath).filter((f) => f.toLowerCase().endsWith('.docx'));
  for (const file of files) {
    console.log(`  Processing DOCX: ${file}`);
    try {
      const filePath = path.join(directoryPath, file);
      const result = await mammoth.extractRawText({ path: filePath });
      const chunks = chunkText(result.value.trim());
      await upsertDocumentChunks(file, 'docx', chunks, { document_title: file.replace(/\.docx$/i, '') });
      console.log(`  ✓ ${file} -> ${chunks.length} chunk(s)`);
    } catch (err) {
      console.error(`  ✗ Failed to process DOCX ${file}:`, err);
    }
  }
}

async function ingestXlsx(directoryPath: string): Promise<void> {
  if (!fs.existsSync(directoryPath)) return;
  console.log(`Reading XLSX from ${directoryPath}...`);
  const files = fs.readdirSync(directoryPath).filter((f) => f.toLowerCase().endsWith('.xlsx'));
  for (const file of files) {
    console.log(`  Processing XLSX: ${file}`);
    try {
      const filePath = path.join(directoryPath, file);
      const workbook = xlsx.readFile(filePath);
      const sections = workbook.SheetNames.map((sheetName) => {
        const csv = xlsx.utils.sheet_to_csv(workbook.Sheets[sheetName]);
        return `Sheet: ${sheetName}\n${csv}`;
      });
      const chunks = chunkText(sections.join('\n\n'));
      await upsertDocumentChunks(file, 'xlsx', chunks, { document_title: file.replace(/\.xlsx$/i, '') });
      console.log(`  ✓ ${file} -> ${chunks.length} chunk(s)`);
    } catch (err) {
      console.error(`  ✗ Failed to process XLSX ${file}:`, err);
    }
  }
}

async function ingestMd(directoryPath: string): Promise<void> {
  if (!fs.existsSync(directoryPath)) return;
  console.log(`Reading Markdown from ${directoryPath}...`);
  const files = fs.readdirSync(directoryPath).filter((f) => f.toLowerCase().endsWith('.md'));
  for (const file of files) {
    console.log(`  Processing MD: ${file}`);
    try {
      const filePath = path.join(directoryPath, file);
      const text = fs.readFileSync(filePath, 'utf8').trim();
      const chunks = chunkText(text);
      await upsertDocumentChunks(file, 'md', chunks, { document_title: file.replace(/\.md$/i, '') });
      console.log(`  ✓ ${file} -> ${chunks.length} chunk(s)`);
    } catch (err) {
      console.error(`  ✗ Failed to process MD ${file}:`, err);
    }
  }
}

async function main() {
  console.log('Starting ingestion pipeline...');
  const args = process.argv.slice(2).filter((a) => !a.startsWith('--'));
  const limitArg = process.argv.find((a) => a.startsWith('--limit='));
  const limit = limitArg ? Number(limitArg.split('=')[1]) : undefined;

  const dataDir = args[0] || path.resolve(process.cwd(), 'datasets');
  const sitemapIndexUrl = args[1] || DEFAULT_SITEMAP_INDEX;

  // File-based ingestion (local datasets/ directory).
  // ingestPDFs kept disabled by default: pdf-parse's require/export shape
  // needs verification against the installed version before enabling in
  // production ingestion runs. DOCX/XLSX/MD cover the current dataset.
  // await ingestPDFs(dataDir);
  await ingestDocx(dataDir);
  await ingestXlsx(dataDir);
  await ingestMd(dataDir);

  // Full-site hybrid crawl: sitemap-driven for coverage, URL-pattern section
  // tagging for the widget's category filter pills (src/lib/sectionMapping.ts).
  // Pass --limit=N to cap total pages processed (useful for a smoke test
  // before burning free-tier embedding quota on a full run).
  await ingestWebsite(sitemapIndexUrl, limit);

  console.log('\n✓ Ingestion complete!');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
